/**
 * Backward-compatibility guard for the report renderers.
 *
 * Two kinds of callers must keep getting exactly what v0.3.0 produced, whatever
 * optional features later versions add:
 *  - work directories in the field, whose target.json has only the fields
 *    v0.3.0 knew (no `plan`, no `tiers`);
 *  - code that calls the renderers the v0.3.0 way (eval/, older tests): no
 *    target view, no extras.
 *
 * The golden files under test/fixtures/target-v0.3.0/ were generated by the
 * v0.3.0 renderers from the fixture below. This test fails on ANY byte of
 * drift in those renderers when the newer optional inputs are absent. For the
 * dashboard the guarded part is the embedded data: its inline script grows as
 * sections are added.
 *
 * If a guarded renderer is changed on purpose, regenerate the golden files
 * deliberately (render the fixture below and review the diff) — never to make
 * a red test green.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildProfile } from '../src/report/profile.js';
import { loadTargetSpec, buildTargetView } from '../src/target/targetProfile.js';
import { renderRemediationMarkdown } from '../src/report/remediationMarkdown.js';
import { buildTargetProfile } from '../src/report/targetJson.js';
import { renderGapMarkdown } from '../src/report/gapMarkdown.js';
import { renderDashboardHtml } from '../src/report/htmlDashboard.js';
import { hashAssessment } from '../src/util/hash.js';

const FIXTURE_DIR = new URL('./fixtures/target-v0.3.0/', import.meta.url);
const NOW = '2026-01-01T00:00:00.000Z';

const CSF = {
  frameworkVersion: 'CSF 2.0',
  sample: false,
  functions: [
    { id: 'GV', name: 'GOVERN' },
    { id: 'ID', name: 'IDENTIFY' },
    { id: 'PR', name: 'PROTECT' },
    { id: 'RC', name: 'RECOVER' },
  ],
  subcategories: [
    sub('GV.OC-01', 'Mission understood', 'GOVERN', 'Organizational Context (GV.OC)', ['Share the mission']),
    sub('GV.OC-02', 'Stakeholders understood', 'GOVERN', 'Organizational Context (GV.OC)', ['Identify stakeholders', 'Review expectations yearly']),
    sub('ID.AM-01', 'Hardware inventoried', 'IDENTIFY', 'Asset Management (ID.AM)', ['Maintain a hardware inventory']),
    sub('PR.AA-01', 'Identities managed', 'PROTECT', 'Identity Management (PR.AA)', ['Maintain identity inventory']),
    sub('PR.AA-05', 'Access enforced', 'PROTECT', 'Identity Management (PR.AA)', ['Require MFA']),
    sub('PR.AA-06', 'Physical access managed', 'PROTECT', 'Identity Management (PR.AA)', []),
    sub('RC.RP-01', 'Recovery plan executed', 'RECOVER', 'Incident Recovery Plan Execution (RC.RP)', ['Begin recovery procedures']),
  ],
};

function sub(id, outcome, fnName, category, examples) {
  return {
    id,
    outcome,
    function: fnName,
    category,
    functionId: id.split('.')[0],
    functionName: fnName,
    categoryId: id.split('-')[0],
    implementationExamples: examples,
  };
}

function assessment(id, coverage, { file = 'policy.md', page = null, downgraded = false } = {}) {
  return {
    subcategory_id: id,
    coverage,
    confidence: coverage === 'none' ? 0.3 : 0.7,
    evidence: coverage === 'none'
      ? []
      : [{ source_file: file, page, score: 0.5, quote: `evidence quote for ${id}`, verified: true }],
    rationale: `rationale for ${id}`,
    needs_review: coverage !== 'substantial',
    verifier_action: downgraded ? 'downgraded_to_none_no_valid_quote' : null,
    verification: { quotes_checked: 1, quotes_verified: downgraded ? 0 : 1, downgraded },
    assessed_at: '2025-12-19T12:30:00.000Z',
  };
}

function review(a, extra = {}) {
  return {
    subcategory_id: a.subcategory_id,
    decision: 'accept',
    final_coverage: a.coverage,
    note: null,
    reviewed_by: 'reviewer@example.org',
    reviewed_at: '2025-12-20T09:00:00.000Z',
    reviewed_against: hashAssessment(a),
    ...extra,
  };
}

const CTX = {
  config: { analysis: { strict: false }, embeddings: { provider: 'mock' }, llm: { provider: 'mock' } },
  now: () => NOW,
};

function buildFixtureProfile() {
  const assessments = {
    'GV.OC-01': assessment('GV.OC-01', 'substantial'),
    'GV.OC-02': assessment('GV.OC-02', 'none', { downgraded: true }),
    'ID.AM-01': assessment('ID.AM-01', 'partial', { file: 'asset-procedure.docx' }),
    'PR.AA-01': assessment('PR.AA-01', 'partial', { file: 'access-standard.pdf', page: 2 }),
    'PR.AA-05': assessment('PR.AA-05', 'none'),
    'PR.AA-06': assessment('PR.AA-06', 'none'),
    'RC.RP-01': assessment('RC.RP-01', 'partial'),
  };
  const reviews = {
    'GV.OC-01': review(assessments['GV.OC-01']),
    'ID.AM-01': review(assessments['ID.AM-01'], {
      decision: 'override',
      final_coverage: 'substantial',
      note: 'Inventory export reviewed out of band.',
    }),
    'PR.AA-01': review(assessments['PR.AA-01'], { note: 'Quarterly access review minutes requested.' }),
    // Made against an assessment that has since changed => stale.
    'RC.RP-01': review(assessments['RC.RP-01'], { reviewed_against: 'outdated-hash' }),
  };
  const meta = {
    embedder_id: 'mock',
    llm_id: 'mock',
    ingested_at: '2025-12-18T08:00:00.000Z',
    analyzed_at: '2025-12-19T12:30:00.000Z',
    ingest_report: { parsed: 3, skipped: 0, failed: 0 },
  };
  const profile = buildProfile(CTX, { csf: CSF, assessments, reviews, meta });
  // Pin the tool stamp so the golden files do not change with every release.
  profile.tool = { name: 'csf-tool', version: 'test' };
  return profile;
}

function golden(name) {
  return readFileSync(new URL(name, FIXTURE_DIR), 'utf8');
}

function dataBlock(html) {
  return /<script id="csf-data" type="application\/json">([\s\S]*?)<\/script>/.exec(html)[1];
}

async function loadV030Target() {
  const warnings = [];
  const spec = await loadTargetSpec(fileURLToPath(new URL('target.json', FIXTURE_DIR)), {
    csf: CSF,
    logger: { warn: (m) => warnings.push(m) },
  });
  return { spec, warnings };
}

test('a v0.3.0 target profile loads without warnings', async () => {
  const { spec, warnings } = await loadV030Target();
  assert.deepEqual(warnings, []);
  assert.equal(spec.default, 'substantial');
});

test('a v0.3.0 target profile renders byte-identically to v0.3.0', async () => {
  const profile = buildFixtureProfile();
  const { spec } = await loadV030Target();
  const view = buildTargetView(profile, spec, CSF);

  assert.equal(renderRemediationMarkdown(profile, view), golden('remediation-plan.md'));
  assert.equal(renderGapMarkdown(profile, { targetView: view }), golden('gap-analysis.md'));
  assert.equal(JSON.stringify(buildTargetProfile(profile, view), null, 2) + '\n', golden('target-profile.json'));
  assert.equal(dataBlock(renderDashboardHtml(profile, view)) + '\n', golden('dashboard-data.json'));
});

test('renderers called the v0.3.0 way (no target, no extras) are unchanged too', () => {
  const profile = buildFixtureProfile();
  assert.equal(renderGapMarkdown(profile, {}), golden('gap-analysis.no-target.md'));
  assert.equal(dataBlock(renderDashboardHtml(profile, null)) + '\n', golden('dashboard-data.no-target.json'));
});
